class Solution:
    def subsets(self, nums):
        res = []
        path = []
        def dfs(start):
            res.append(path)
            for i in range(start, len(nums)):
                path.append(nums[i])
                dfs(i + 1)
                path.pop()
        dfs(0)
        return res
